INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Farbmodell immer additive Farben verwendet?', 2, '[{"text": "Nein", "correct": true, "because": "CMYK ist subtraktiv"}, {"text": "Ja", "correct": false, "because": "Nicht alle Modelle sind additiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Farben kombiniere ich, um Weiß auf einem Bildschirm zu erzeugen?', 3, '[{"text": "Rot, Grün, Blau", "correct": true, "because": "Additive Mischung ergibt Weiß"}, {"text": "Cyan, Magenta, Gelb", "correct": false, "because": "Für Druck"}, {"text": "Rot, Gelb, Blau", "correct": false, "because": "Nicht digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein additives Farbsystem effektiv?', 5, '[{"text": "Variable Intensität", "correct": true, "because": "Erlaubt Farbabstufung"}, {"text": "Breites Farbspektrum", "correct": true, "because": "Mehr Farben darstellbar"}, {"text": "Hoher Papierverbrauch", "correct": false, "because": "Irrelevant für Bildschirme"}, {"text": "Feste Farbtöne", "correct": false, "because": "Einschränkt Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rot, Grün, Blau mischen ergibt Weiß. b) Es wird für Druck verwendet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, für Bildschirme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit einem digitalen Farbsystem?', 4, '[{"text": "Farbwerte", "correct": false, "because": "Bestimmen die Farbe"}, {"text": "Bildschirmkalibrierung", "correct": false, "because": "Sichert Genauigkeit"}, {"text": "Druckertyp", "correct": true, "because": "Für Bildschirme irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob alle Farben auf einem Monitor durch drei Grundfarben erzeugt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Rot, Grün, Blau genügen"}, {"text": "Nein", "correct": false, "because": "Additives Modell vollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Wertebereich wird für jede Farbkomponente verwendet?', 4, '[{"text": "0 bis 255", "correct": true, "because": "8-Bit pro Kanal"}, {"text": "0 bis 100", "correct": false, "because": "Prozent für andere Modelle"}, {"text": "1 bis 256", "correct": false, "because": "Falscher Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass dieses Farbsystem für alle Geräte gilt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Drucker nutzen CMYK"}, {"text": "Ja", "correct": false, "because": "Nur für Bildschirme"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erzeugt die Abwesenheit von Farben auf einem Bildschirm Schwarz?', 2, '[{"text": "Ja", "correct": true, "because": "Keine Intensität ergibt Schwarz"}, {"text": "Nein", "correct": false, "because": "Null-Werte sind Schwarz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Farben mische ich, um Gelb auf einem Bildschirm zu erzeugen?', 4, '[{"text": "Rot und Grün", "correct": true, "because": "Additive Mischung ergibt Gelb"}, {"text": "Blau und Grün", "correct": false, "because": "Ergibt Cyan"}, {"text": "Rot und Blau", "correct": false, "because": "Ergibt Magenta"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Arbeit mit einem Farbsystem für Monitore?', 4, '[{"text": "Präzise Werte", "correct": true, "because": "Sichert genaue Farben"}, {"text": "Minimale Werte", "correct": false, "because": "Einschränkt Farben"}, {"text": "Papierqualität", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) (255, 255, 255) ergibt Weiß. b) Es wird für Druckfarben genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nicht für Druck"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Farben auf einem Bildschirm zu definieren?', 3, '[{"text": "Farbwerte", "correct": false, "because": "Bestimmen die Farbe"}, {"text": "Intensität", "correct": false, "because": "Steuert Helligkeit"}, {"text": "Druckertinte", "correct": true, "because": "Nur für Druck"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Farbe Schwarz definiere?', 4, '[{"text": "(0, 0, 0)", "correct": true, "because": "Keine Intensität ergibt Schwarz"}, {"text": "(255, 255, 255)", "correct": false, "because": "Ergibt Weiß"}, {"text": "(100, 100, 100)", "correct": false, "because": "Ergibt Grau"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass dieses Farbsystem für alle Bildschirme gleich ist. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Standard für digitale Anzeigen"}, {"text": "Nein", "correct": false, "because": "Universell für Bildschirme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis erhalte ich bei der Mischung von (255, 0, 0) und (0, 255, 0)?', 4, '[{"text": "Gelb", "correct": true, "because": "Rot plus Grün ergibt Gelb"}, {"text": "Blau", "correct": false, "because": "Falsche Komponenten"}, {"text": "Weiß", "correct": false, "because": "Braucht alle Farben"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Blau durch (0, 0, 255) definiert?', 2, '[{"text": "Ja", "correct": true, "because": "Nur Blau auf Maximum"}, {"text": "Nein", "correct": false, "because": "Korrekte Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet dieses Farbsystem für Bildschirme?', 5, '[{"text": "Breite Farbdarstellung", "correct": true, "because": "Viele Kombinationen möglich"}, {"text": "Einfache Steuerung", "correct": true, "because": "Drei Komponenten"}, {"text": "Geringer Stromverbrauch", "correct": false, "because": "Kein Farbfaktor"}, {"text": "Papierkompatibilität", "correct": false, "because": "Nicht für Druck"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Farbdefinition unwichtig?', 3, '[{"text": "Intensität", "correct": false, "because": "Bestimmt Farbton"}, {"text": "Wertebereich", "correct": false, "because": "Sichert Genauigkeit"}, {"text": "Dateiformat", "correct": true, "because": "Kein Farbfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich eine Farbe für einen Bildschirm definiere?', 4, '[{"text": "Werte für Rot, Grün, Blau setzen", "correct": true, "because": "Definiert Farbe präzise"}, {"text": "CMYK-Werte wählen", "correct": false, "because": "Für Druck, nicht Bildschirm"}, {"text": "Zufällige Werte", "correct": false, "because": "Unpräzise"}]');
